#include <iostream>
#include <utility>

void bump_copy(int value) { ++value; std::cout << value << '\n'; }
void bump_reference(int& value) { ++value; }
void category(int&) { std::cout << "lvalue\n"; }
void category(const int&) { std::cout << "const-reference\n"; }
void category(int&&) { std::cout << "rvalue\n"; }

int main() {
    int shares = 7;
    bump_copy(shares);
    std::cout << shares << '\n';
    bump_reference(shares);
    std::cout << shares << '\n';
    category(shares);
    category(9);
    int&& named = 10;
    category(named);
    category(std::move(named));
    const int fixed = 11;
    category(std::move(fixed));
}

#include <iostream>
#include <string>
#include <string_view>
#include <utility>

std::string owned_label() { return "owned"; }

int main() {
    std::string text = "risk";
    std::string_view view = text;
    std::cout << view.substr(0, 2) << '\n';
    const std::string copied = text;
    view = {}; // Discard this observer before owner mutation/transfer.
    std::string moved = std::move(text);
    std::cout << moved << '\n';
    std::cout << copied << '\n';
    text = "new"; // Reassign the valid but otherwise unspecified moved-from string.
    std::cout << text << '\n';
    const std::string& extended = std::string{"local"};
    std::cout << extended << '\n';
    std::cout << owned_label() << '\n';
}
